<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>SandBox CA</title>
    <style>
        :root {
            --bg-color: #1a1a1a;
            --panel-color: #2d2d2d;
            --text-color: #eee;
            --accent: #4a90e2;
            --sand-color: #edc9af;
            --water-color: #4fa3ff;
            --wall-color: #888;
            --acid-color: #adff2f;
            --empty-color: #1a1a1a;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            margin: 0;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            overflow: hidden;
        }

        .container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 20px;
            padding: 20px;
            background: var(--panel-color);
            border-radius: 12px;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }

        canvas {
            background-color: #000;
            border: 4px solid #444;
            image-rendering: pixelated;
            cursor: crosshair;
            width: 400px;
            height: 400px;
            display: block;
        }

        .controls {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 10px;
            max-width: 420px;
        }

        button {
            padding: 10px 16px;
            border: none;
            border-radius: 6px;
            cursor: pointer;
            font-weight: bold;
            transition: transform 0.1s, filter 0.2s;
            text-transform: uppercase;
            font-size: 12px;
            user-select: none;
        }

        button:active {
            transform: scale(0.95);
        }

        button:hover {
            filter: brightness(1.2);
        }

        #mat-sand { background: var(--sand-color); color: #444; }
        #mat-water { background: var(--water-color); color: #fff; }
        #mat-wall { background: var(--wall-color); color: #fff; }
        #mat-acid { background: var(--acid-color); color: #444; }
        #mat-empty { background: #555; color: #fff; }
        #clear { background: #ff4d4d; color: #fff; margin-left: 10px; }

        .selected {
            outline: 3px solid white;
            box-shadow: 0 0 10px rgba(255,255,255,0.5);
        }
    </style>
</head>
<body>

<div class="container">
    <canvas id="sand" width="100" height="100"></canvas>
    <div class="controls">
        <button id="mat-sand" onclick="setMaterial('sand')">Sand</button>
        <button id="mat-water" onclick="setMaterial('water')">Water</button>
        <button id="mat-wall" onclick="setMaterial('wall')">Wall</button>
        <button id="mat-acid" onclick="setMaterial('acid')">Acid</button>
        <button id="mat-empty" onclick="setMaterial('empty')">Eraser</button>
        <button id="clear" onclick="sim.clear()">Clear All</button>
    </div>
</div>

<script>
    const CANVAS_SIZE = 100; // Grid dimensions (w, h)
    const canvas = document.getElementById('sand');
    const ctx = canvas.getContext('2d', { alpha: false });

    let currentMaterial = 'sand';
    let isMouseDown = false;

    // Material Color Map
    const colors = {
        empty: '#1a1a1a',
        sand: '#edc9af',
        water: '#4fa3ff',
        wall: '#888',
        acid: '#adff2f'
    };

    // Simulation State
    const grid = Array(CANVAS_SIZE).fill(null).map(() => Array(CANVAS_SIZE).fill('empty'));

    window.sim = {
        w: CANVAS_SIZE,
        h: CANVAS_SIZE,
        get(x, y) {
            if (x < 0 || x >= CANVAS_SIZE || y < 0 || y >= CANVAS_SIZE) return 'wall'; // Edges act as walls
            return grid[y][x];
        },
        set(x, y, material) {
            if (x >= 0 && x < CANVAS_SIZE && y >= 0 && y < CANVAS_SIZE) {
                grid[y][x] = material;
            }
        },
        clear() {
            for (let y = 0; y < CANVAS_SIZE; y++) {
                grid[y].fill('empty');
            }
        },
        tick(n = 1) {
            for (let t = 0; t < n; t++) {
                // Process bottom-up to prevent teleporting
                for (let y = CANVAS_SIZE - 1; y >= 0; y--) {
                    for (let x = 0; x < CANVAS_SIZE; x++) {
                        const mat = grid[y][x];
                        if (mat === 'empty' || mat === 'wall') continue;

                        if (mat === 'sand') {
                            this.updateSand(x, y);
                        } else if (mat === 'water') {
                            this.updateLiquid(x, y, 'water');
                        } else if (mat === 'acid') {
                            this.updateAcid(x, y);
                        }
                    }
                }
            }
        },
        updateSand(x, y) {
            // 1. Fall straight down into empty or liquids
            if (y < CANVAS_SIZE - 1) {
                const below = grid[y+1][x];
                if (below === 'empty' || below === 'water' || below === 'acid') {
                    this.swap(x, y, x, y + 1);
                    return;
                }
            }
            // 2. Slide diagonally
            const dir = Math.random() < 0.5 ? -1 : 1;
            for (let i of [dir, -dir]) {
                let nx = x + i;
                if (nx >= 0 && nx < CANVAS_SIZE && y < CANVAS_SIZE - 1) {
                    const diag = grid[y+1][nx];
                    if (diag === 'empty' || diag === 'water' || diag === 'acid') {
                        this.swap(x, y, nx, y + 1);
                        return;
                    }
                }
            }
        },
        updateLiquid(x, y, type) {
            // Fall straight down
            if (y < CANVAS_SIZE - 1 && grid[y+1][x] === 'empty') {
                this.swap(x, y, x, y + 1);
                return;
            }
            // Spread horizontally
            const dir = Math.random() < 0.5 ? -1 : 1;
            for (let i of [dir, -dir]) {
                let nx = x + i;
                if (nx >= 0 && nx < CANVAS_SIZE && grid[y][nx] === 'empty') {
                    this.swap(x, y, nx, y);
                    return;
                }
            }
        },
        updateAcid(x, y) {
            // Acid dissolves things it touches below or beside
            const targets = [[0, 1], [-1, 0], [1, 0]];
            for (let [dx, dy] of targets) {
                let nx = x + dx, ny = y + dy;
                if (nx >= 0 && nx < CANVAS_SIZE && ny >= 0 && ny < CANVAS_SIZE) {
                    const targetMat = grid[ny][nx];
                    if (targetMat === 'sand' || targetMat === 'wall') {
                        grid[ny][nx] = 'empty';
                        grid[y][x] = 'empty'; // Acid is consumed in reaction
                        return;
                    }
                }
            }
            // If no dissolution, move like water
            this.updateLiquid(x, y, 'acid');
        },
        swap(x1, y1, x2, y2) {
            const temp = grid[y1][x1];
            grid[y1][x1] = grid[y2][x2];
            grid[y2][x2] = temp;
        }
    };

    // UI Logic
    function setMaterial(mat) {
        currentMaterial = mat;
        document.querySelectorAll('.controls button').forEach(btn => btn.classList.remove('selected'));
        const activeBtn = document.getElementById(`mat-${mat}`);
        if (activeBtn) activeBtn.classList.add('selected');
    }

    function paint(e) {
        const rect = canvas.getBoundingClientRect();
        const scaleX = CANVAS_SIZE / rect.width;
        const scaleY = CANVAS_SIZE / rect.height;
        const x = Math.floor((e.clientX - rect.left) * scaleX);
        const y = Math.floor((e.clientY - rect.top) * scaleY);
        sim.set(x, y, currentMaterial);
    }

    canvas.addEventListener('mousedown', (e) => { isMouseDown = true; paint(e); });
    window.addEventListener('mouseup', () => { isMouseDown = false; });
    canvas.addEventListener('mousemove', (e) => { if (isMouseDown) paint(e); });

    function render() {
        const imgData = ctx.createImageData(CANVAS_SIZE, CANVAS_SIZE);
        const data = imgData.data;

        for (let y = 0; y < CANVAS_SIZE; y++) {
            for (let x = 0; x < CANVAS_SIZE; x++) {
                const mat = grid[y][x];
                const colorHex = colors[mat];
                const r = parseInt(colorHex.slice(1, 3), 16);
                const g = parseInt(colorHex.slice(3, 5), 16);
                const b = parseInt(colorHex.slice(5, 7), 16);

                const idx = (y * CANVAS_SIZE + x) * 4;
                data[idx] = r;
                data[idx + 1] = g;
                data[idx + 2] = b;
                data[idx + 3] = 255;
            }
        }
        ctx.putImageData(imgData, 0, 0);
    }

    function loop() {
        sim.tick(1);
        render();
        requestAnimationFrame(loop);
    }

    // Init
    setMaterial('sand');
    loop();

</script>
</body>
</html>
